from pathlib import Path

import pytest
from pytest_bdd.scenario import scenario_wrapper_template_registry


def scenario_feature_path(item: pytest.Item) -> Path | None:
    """Return the feature path for a test generated by pytest-bdd."""
    if isinstance(item, pytest.Function):
        scenario = scenario_wrapper_template_registry.get(item.function)
        if scenario is not None:
            return Path(scenario.feature.filename).resolve()
    return None
